// Caliper's canonical `extract --json` as the oracles read it. The output interns what components share, so a component's
// props, its curated inherited props and a collapsed layer's member names each need one step to read; they are here so
// every script reads them the same way. Pure.

/** A map of prop name to prop id as one record. A component's `props` and `notableInherited` are that map inline, or (schema
 * 2) an array of prop-set ids, each such a map in `propSets`. */
export function propMap(caliper: any, list: unknown): Record<string, string> {
  if (Array.isArray(list)) return Object.assign({}, ...list.map((id: string) => caliper.propSets[id]))
  return (list as Record<string, string> | undefined) ?? {}
}

/** The props a props table lists for a component: its own, then the curated props inherited from a collapsed source
 * (`notableInherited`, `crates/core/src/pipeline/rdt.rs`). A prop named in both is the component's own. */
export function listedProps(caliper: any, component: any): Record<string, string> {
  return { ...propMap(caliper, component.notableInherited), ...propMap(caliper, component.props) }
}

/** The prop names a collapsed layer lists. The canonical JSON interns the list: `members` is an id into `nameLists`; an
 * older output lists the names inline. */
export function layerMembers(caliper: any, layer: any): string[] {
  const { members } = layer
  if (typeof members === 'string') return caliper.nameLists?.[members] ?? []
  return members ?? []
}
// Validates the canonical JSON the oracle reads, so a renamed key or a dangling id stops the run with its cause
// instead of shrinking the set of props compared.

/** The canonical JSON shape this oracle reads (`SCHEMA_VERSION` in crates/core/src/types/output.rs). */
export const SUPPORTED_SCHEMA_VERSION = 4

/** Throws unless `caliper` has the keys the oracle reads, at the schema version it understands. */
export function checkCaliperShape(caliper: any): void {
  if (caliper?.schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    throw new Error(
      `caliper output has schemaVersion ${JSON.stringify(caliper?.schemaVersion)}, the oracle reads ${SUPPORTED_SCHEMA_VERSION}`,
    )
  }
  for (const key of ['components', 'propSets', 'props'] as const) {
    if (typeof caliper[key] !== 'object' || caliper[key] === null) {
      throw new Error(`caliper output has no "${key}" object`)
    }
  }
}

/** One map of prop name to prop id for a component, merged from the prop sets it lists. */
export function flattenProps(caliper: any, componentKey: string, component: any): Record<string, string> {
  if (!Array.isArray(component.props)) return component.props
  const merged: Record<string, string> = {}
  for (const id of component.props) {
    const set = caliper.propSets[id]
    if (set === undefined) throw new Error(`component ${componentKey} lists prop set ${id}, which propSets lacks`)
    Object.assign(merged, set)
  }
  return merged
}

/** Throws when a comparison compared nothing, which a gate must not report as clean. */
export function requireComparison(propsShared: number, componentsMatched: number): void {
  if (propsShared === 0) {
    throw new Error(`the comparison is empty: ${componentsMatched} components matched, 0 shared props compared`)
  }
}
